#!/bin/sh
# Local Kotlin-only compile check for the CordiAct app module.
# The SDK's aidl binary is x86_64 and cannot run on this phone, so AIDL stubs are
# generated by hand for the check and the real .aidl sources are put back after.
set -e
STASH=$(mktemp -d)
cd "$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
python3 /workspace/spike/gen_aidl_stub.py app/src/main/java \
  app/src/main/aidl/com/cordiact/app/sandbox/ISandboxJsPoc.aidl \
  app/src/main/aidl/com/cordiact/app/sandbox/ISandboxProbe.aidl \
  app/src/main/aidl/com/cordiact/app/privilege/IPrivilegedService.aidl >/dev/null
mv app/src/main/aidl "$STASH/aidl"
cleanup() {
  rm -f app/src/main/java/com/cordiact/app/sandbox/ISandboxProbe.java \
        app/src/main/java/com/cordiact/app/sandbox/ISandboxJsPoc.java \
        app/src/main/java/com/cordiact/app/privilege/IPrivilegedService.java
  rm -rf app/src/main/aidl
  mv "$STASH/aidl" app/src/main/aidl
  rmdir "$STASH"
}
trap cleanup EXIT
./gradlew :app:compileDebugKotlin "$@"
